use std::{collections::BTreeMap,fs,path::PathBuf};
use symbrowse_core::{state::{State,FILE_MAGIC},state_store::{KeyMaterial,Store}};
fn sample() -> State { State{schema_version:3,name:"existing".into(),saved_at:String::new(),expires_at:String::new(),key_source:String::new(),origins:BTreeMap::new()} }
fn main(){let root=PathBuf::from(std::env::args().nth(1).expect("owned root"));let encrypted=Store::new(&root,time::Duration::days(30),Some(KeyMaterial::new([0xab;32],"environment").unwrap())).unwrap();encrypted.save_at(&mut sample(),time::OffsetDateTime::now_utc()).unwrap();let before=fs::read(root.join("existing.json")).unwrap();let plaintext=Store::new(&root,time::Duration::days(30),None).unwrap();let result=plaintext.save_at(&mut sample(),time::OffsetDateTime::now_utc());let after=fs::read(root.join("existing.json")).unwrap();let header=after.strip_prefix(FILE_MAGIC).unwrap().split(|b| *b==b'\n').next().unwrap();println!("fresh_snapshot_save_success={}",result.is_ok());println!("retained_bytes_unchanged={}",before==after);println!("result_header={}",String::from_utf8_lossy(header));println!("no_key_load_success={}",plaintext.load("existing").is_ok());}
